// Veille IA - Normalisation multi-sources vers prompt LLM
var items = $input.all();
var articles = [];

// Lire les URLs deja envoyees (injectees par notion-dedup.js)
var seenUrls = {};
items.forEach(function(it) {
  if (it.json && Array.isArray(it.json._seenUrls)) {
    it.json._seenUrls.forEach(function(url) { seenUrls[url] = true; });
  }
});

// Domaines hors-sujet IT
var OFFTOPIC = /molecular biology|thermodynamic equilibrium|political elite|electoral|gerontolog|cognitive impairment|earth observation|epidemi|genomic|drug discovery|medical imaging|ecology\b|climate forecast|seismic|particle physics/i;

function clean(s) {
  return (s || '')
    .replace(/\\textbf\{([^}]*)\}/g, '$1')
    .replace(/\\emph\{([^}]*)\}/g, '$1')
    .replace(/\\[a-z]+\{[^}]*\}/g, '')
    .replace(/\$[^$\n]+\$/g, '')
    .replace(/\*\*/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function truncate(s, maxLen) {
  if (!s || s.length <= maxLen) return s;
  var cut = s.lastIndexOf(' ', maxLen);
  return (cut > maxLen * 0.6 ? s.substring(0, cut) : s.substring(0, maxLen)) + '\u2026';
}

function isSpecificUrl(url) {
  if (!url) return false;
  if (/instagram\.com\/[^/]+\/?(\?|$)/.test(url)) return false;
  if (/youtube\.com\/(channel|c\/|user\/|@)/.test(url)) return false;
  if (/\/(support|fr\/support|outils-ia)\/?(\?|$)/.test(url)) return false;
  var m = url.match(/^https?:\/\/[^/?#]+(\/[^?#]*)/);
  var path = m ? m[1].replace(/\/$/, '') : '';
  return path.length > 10;
}

function categorize(title, summary, type) {
  var text = (title + ' ' + (summary || '')).toLowerCase();
  if (type !== 'news') {
    if (/speculative decod|kv cache|inference speed|token.*per.*second|throughput|latency.*llm|llm.*latency/.test(text)) return 'LLM performance';
    if (/\bagent\b|agentic|gui agent|task planning|multi-agent|autonomous.*action/.test(text)) return 'agents IA';
    if (/reward model|rlhf|reinforcement learning|post.train|fine.tun|grpo|ppo\b/.test(text)) return 'RL et entrainement';
    if (/text-to-image|image generat|diffusion model|image synthes|visual generat/.test(text)) return 'vision IA';
    if (/hallucin|jailbreak|adversarial|safety align|value align|red.team/.test(text)) return 'fiabilite IA';
    if (/benchmark|leaderboard|evaluat.*llm|llm.*evaluat|dataset.*train/.test(text)) return 'benchmark';
    if (/multilingual|translation|reasoning|code generat|coding llm/.test(text)) return 'NLP et raisonnement';
    return 'recherche';
  }
  if (/nouveau modele|new model|deploiement.*modele|modele.*pointe|version \d|release.*model|model.*release/.test(text)) return 'nouveau modele';
  if (/arnaque|phishing|deepfake|cyberattaque|fraud|scam|malveillance|clonage de voix|usurpation/.test(text)) return 'cybersecurite';
  if (/\d+\s*%|millions? (d.utilisateurs|users)|adoption|sondage|etude|rapport.*ia|ia.*rapport|impact.*societe/.test(text)) return 'societe';
  if (/computer.use|nouvelle.*(fonctionnalite|capacite|integration)|connecteur|mise a jour.*ia|ia.*mise a jour/.test(text)) return 'feature produit';
  if (/\boutil\b|outil ia|ai tool|assistant ia|application ia|lancement.*app/.test(text)) return 'outil';
  return 'actualite IA';
}

// 1. HuggingFace Daily Papers
items.forEach(function(it) {
  var d = it.json;
  if (!d.paper || !d.paper.id) return;
  var title = clean(d.paper.title || d.title);
  var summary = clean(d.paper.ai_summary || d.summary);
  if (OFFTOPIC.test(title + ' ' + summary)) return;
  articles.push({
    source: 'HuggingFace',
    category: categorize(title, summary, 'research'),
    title: title,
    summary: truncate(summary, 350),
    url: 'https://huggingface.co/papers/' + d.paper.id,
    upvotes: d.paper.upvotes || 0,
    type: 'research'
  });
});

// 2. arXiv XML Feed
// Look for raw XML string containing feed entries
var arxivArticles = [];
items.forEach(function(it) {
  var d = it.json;
  if (!d.data || typeof d.data !== 'string' || !d.data.includes('<feed')) return;
  var entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
  var match;
  while ((match = entryRegex.exec(d.data)) !== null) {
    var e = match[1];
    var tM = e.match(/<title>([\s\S]*?)<\/title>/);
    var sM = e.match(/<summary>([\s\S]*?)<\/summary>/);
    var lM = e.match(/<link href="([^"]+)" rel="alternate"/);
    if (!tM || !lM) continue;
    var title = clean(tM[1]);
    var summary = clean(sM ? sM[1] : '');
    if (OFFTOPIC.test(title + ' ' + summary)) continue;
    arxivArticles.push({
      source: 'arXiv',
      category: categorize(title, summary, 'research'),
      title: title,
      summary: truncate(summary, 350),
      url: lM[1],
      upvotes: 0,
      type: 'research'
    });
  }
});
articles = articles.concat(arxivArticles.slice(0, 10));

// 3. Messages Perplexity / Recherche IA
items.forEach(function(it) {
  var d = it.json;
  var msgText = typeof d.message === 'string' ? d.message
              : (d.message && typeof d.message.content === 'string') ? d.message.content
              : (d.choices && d.choices[0] && d.choices[0].message && typeof d.choices[0].message.content === 'string') ? d.choices[0].message.content
              : null;
  var cites = d.citations || [];
  if (!msgText || !Array.isArray(cites)) return;
  var msg = msgText;

  // Format A: "- [N] **Source** - texte ... URL: https://..."
  if (/- \[\d+\] \*\*/.test(msg)) {
    var reA = /- \[(\d+)\]\s*\*\*([^*]+)\*\*\s*-\s*([\s\S]+?)(?=\n- \[|\n\n\n|$)/g;
    var m;
    while ((m = reA.exec(msg)) !== null) {
      var n = parseInt(m[1]) - 1;
      var src = m[2].trim();
      var body = m[3];
      var urlM = body.match(/URL: (https?:\/\/[^\s\n]+)/);
      var url = urlM ? urlM[1] : (cites[n] || '');
      if (!url || !isSpecificUrl(url)) continue;
      var text = clean(body.replace(/URL: https?:\/\/[^\s\n]+/, ''));
      var first = text.match(/^(.{10,120})[.;]/);
      var title = first ? first[1] : truncate(text, 120);
      var summary = truncate(text, 350);
      articles.push({
        source: clean(src),
        category: categorize(title, summary, 'news'),
        title: title,
        summary: summary,
        url: url,
        upvotes: 4,
        type: 'news'
      });
    }
  }

  // Format B: "- **Titre**\n  [SOURCE] ...\n  Resume ... [N]\n  URL"
  if (/- \*\*[^*\n]+\*\*/.test(msg) && /\[SOURCE\]/.test(msg)) {
    msg.split(/(?=\n- \*\*)/).forEach(function(seg) {
      var tM = seg.match(/- \*\*([^*\n]+)\*\*/);
      var sM = seg.match(/\[SOURCE\]\s*([^\n]+)/);
      var rM = seg.match(/R[ée]sum[ée]\s*:\s*([\s\S]*?)(?:\n\s*URL|\n\s*---|\n\s*###|$)/);
      if (!tM || !rM) return;
      var resume = rM[1].trim();
      var refs = resume.match(/\[(\d+)\]/g) || [];
      var lastN = refs.length ? parseInt(refs[refs.length - 1].replace(/[\[\]]/g, '')) - 1 : null;
      var url = (lastN !== null && cites[lastN]) ? cites[lastN] : '';
      if (!url || !isSpecificUrl(url)) return;
      resume = truncate(clean(resume.replace(/\[\d+\]/g, '')), 350);
      var srcName = sM ? clean(sM[1]).split(/[\u2013\u2014]/)[0].trim() : 'Veille IA';
      var title = clean(tM[1]);
      articles.push({
        source: srcName.substring(0, 40),
        category: categorize(title, resume, 'news'),
        title: title,
        summary: resume,
        url: url,
        upvotes: 4,
        type: 'news'
      });
    });
  }

  // Format C: parseur generique ligne par ligne
  var seen_local = new Set();
  if (!/- \[\d+\] \*\*/.test(msg) && !(/- \*\*[^*\n]+\*\*/.test(msg) && /\[SOURCE\]/.test(msg))) {
    var lines = msg.split(/\n/);
    for (var li = 0; li < lines.length; li++) {
      var line = lines[li].trim();
      if (!line) continue;
      if (/^(ainsi qu|voici|recherche|source|les act|les nou|###|---|\*\*\*)/i.test(line)) continue;
      if (/^\d+\.?\s*$/.test(line)) continue;
      var urlM = line.match(/(https?:\/\/[^\s\n,;)\]>]+)/);
      if (!urlM) continue;
      var url = urlM[1].replace(/[)\]>,;]+$/, '');
      if (!isSpecificUrl(url) || seen_local.has(url)) continue;
      var desc = line.substring(0, urlM.index).replace(/^[-\u2022*]\s*/, '').replace(/URL:\s*/i, '').trim();
      var srcM = desc.match(/^\[([^\]]+)\]/);
      var source = srcM ? srcM[1].trim() : 'Perplexity';
      var text = srcM ? desc.substring(srcM[0].length).trim() : desc;
      var first = text.match(/^(.{15,120})[\.;]/);
      var title = first ? first[1].trim() : text.substring(0, 100).replace(/\s+$/, '');
      var summary = text.length > 350 ? text.substring(0, 350) : text;
      seen_local.add(url);
      articles.push({
        source: source,
        category: categorize(title, summary, 'news'),
        title: title,
        summary: summary,
        url: url,
        upvotes: 4,
        type: 'news'
      });
    }
  }
});

// Deduplication par URL
var seen = {};
articles = articles.filter(function(a) {
  if (!a.url || seen[a.url] || seenUrls[a.url]) return false;
  seen[a.url] = true;
  return true;
});

if (articles.length === 0) {
  return { prompt: "Aucune actualite aujourd'hui.", total: 0, articles: [] };
}

// Tri: news en tete, puis research par upvotes decroissants
articles.sort(function(a, b) {
  if (a.type === 'news' && b.type !== 'news') return -1;
  if (a.type !== 'news' && b.type === 'news') return 1;
  return b.upvotes - a.upvotes;
});

// Construction du prompt
var today = new Date().toLocaleDateString('fr-FR', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

var newsCount = articles.filter(function(a) { return a.type === 'news'; }).length;

var lines = [
  'Date : ' + today,
  articles.length + ' actualites disponibles (' + newsCount + ' actualites industrie + ' + (articles.length - newsCount) + ' papers de recherche).',
  '',
  '== ARTICLES ============================================'
];

articles.forEach(function(a, i) {
  lines.push('');
  lines.push((i + 1) + '. [' + a.source + ' ' + a.category + '] ' + a.title);
  if (a.summary) lines.push('   ' + a.summary);
  lines.push('   URL: ' + a.url);
  if (a.upvotes > 0) lines.push('   (' + a.upvotes + ' upvotes)');
});

lines.push('');
lines.push('====================================================');
lines.push('');
lines.push('MISSION:');
lines.push('Selectionne exactement 10 articles en respectant ce mix:');
lines.push('  - Idealement au moins 4 articles News (numeros 1 a ' + newsCount + ' dans la liste)');
lines.push('  - Si moins de 4 News disponibles, completer avec des Research supplementaires');
lines.push('  - Au moins 4 articles Research (papers pertinents pour des praticiens IT)');
lines.push('  - Le reste au choix selon la pertinence');
lines.push('');
lines.push('Pour chaque article retenu:');
lines.push('  - Titre cliquable vers URL ci-dessus');
lines.push('  - Badge type: Research | News | Outil');
lines.push('  - 2-3 phrases de resume en francais');
lines.push('');
lines.push('En-tete attendu: "Veille IA - ' + today + '"');

return {
  prompt: lines.join('\n'),
  total: articles.length,
  articles: articles
};

// ====================================================
// Veille IA — Sauvegarde top 10 LLM → Notion
// Reçoit la sortie HTML du LLM (champ "output")
// Extrait les articles sélectionnés et les persiste
// ====================================================

// Nettoyer les éventuelles balises markdown autour du HTML
var raw = ($input.first().json.output || '')
  .replace(/^```html\s*/i, '')
  .replace(/\s*```\s*$/, '');

var now = new Date().toISOString();
var saved = 0;
var skipped = 0;
var errors = [];

// ── Extraction des articles depuis le HTML ──
// Deux patterns possibles selon le format du LLM :
// (A) Blocs <div class="article"> avec <span class="badge"> + <h2><a href>
// (B) Fallback : tous les <h2><a href="..."> présents dans le HTML

var articles = [];

// Tentative (A) : blocs structurés
var blocks = raw.match(/<div[^>]*class="article"[^>]*>[\s\S]*?<\/div>/g) || [];

if (blocks.length > 0) {
  blocks.forEach(function(block) {
    var badgeM = block.match(/<span[^>]*>([\s\S]*?)<\/span>/);
    var linkM  = block.match(/<h2[^>]*>[\s\S]*?<a\s+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!linkM) return;
    articles.push({
      url:   linkM[1],
      title: linkM[2].replace(/<[^>]+>/g, '').trim(),
      badge: badgeM ? badgeM[1].replace(/<[^>]+>/g, '').trim() : ''
    });
  });
}

// Fallback (B) : si le LLM a produit un HTML sans classes d'articles
if (articles.length === 0) {
  var h2Re = /<h2[^>]*>[\s\S]*?<a\s+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
  var m;
  while ((m = h2Re.exec(raw)) !== null) {
    articles.push({
      url:   m[1],
      title: m[2].replace(/<[^>]+>/g, '').trim(),
      badge: ''
    });
  }
}

// ── Envoi vers Notion ──
for (var i = 0; i < articles.length; i++) {
  var a = articles[i];
  if (!a.url || !a.title) { skipped++; continue; }

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.notion.com/v1/pages',
      headers: {
        'Authorization':   'Bearer PLACEHOLDER_NOTION_TOKEN_SOPS',
        'Notion-Version':  '2022-06-28',
        'Content-Type':    'application/json'
      },
      body: {
        parent: { database_id: '38c15cc8-89a0-819c-b577-ec51eb502688' },
        properties: {
          'Titre article': { title:     [{ text: { content: a.title.substring(0, 150) } }] },
          'URL':           { url:       a.url },
          'Source':        { rich_text: [{ text: { content: a.badge.substring(0, 50)  } }] },
          'Vu le':         { date:      { start: now } }
        }
      }
    });
    saved++;
  } catch(e) {
    errors.push({ url: a.url, error: e.message });
  }
}

return [{ json: {
  saved:   saved,
  skipped: skipped,
  total:   articles.length,
  errors:  errors
} }];

var out=$input.first().json; var html=out.output||out.text||'';
if(!html||html.trim()===''){html='<div style="font-family:sans-serif;padding:20px"><h2>Veille IA</h2><p>Aucune actualite aujourd hui.</p></div>';}
return {html_body:html};

// ====================================================
// Veille IA — Déduplication Notion
// Positionner CE NODE entre le Merge et normalisation-prompt.js
//
// Ce node :
//   1. Interroge Notion pour récupérer toutes les URLs déjà envoyées
//   2. Passe tous les items originaux inchangés
//   3. Ajoute un item spécial { _seenUrls: [...] } en fin de liste
//
// normalisation-prompt.js lit _seenUrls et filtre les articles déjà vus.
// ====================================================

var NOTION_TOKEN = 'PLACEHOLDER_NOTION_TOKEN_SOPS';
var DATABASE_ID  = '38c15cc8-89a0-819c-b577-ec51eb502688';

var headers = {
  'Authorization':  'Bearer ' + NOTION_TOKEN,
  'Notion-Version': '2022-06-28',
  'Content-Type':   'application/json'
};

// ── Récupérer toutes les URLs Notion (pagination) ──
var seenUrls = {};
var hasMore = true;
var startCursor = null;

try {
  while (hasMore) {
    var body = { page_size: 100 };
    if (startCursor) body.start_cursor = startCursor;

    var resp = await this.helpers.httpRequest({
      method:  'POST',
      url:     'https://api.notion.com/v1/databases/' + DATABASE_ID + '/query',
      headers: headers,
      body:    body
    });

    (resp.results || []).forEach(function(page) {
      var props = page.properties || {};
      var url   = props['URL'] && props['URL'].url;
      if (url) seenUrls[url] = true;
    });

    hasMore      = resp.has_more;
    startCursor  = resp.next_cursor || null;
  }
} catch(e) {
  // En cas d'erreur Notion, on continue sans filtrer plutôt que de bloquer
  seenUrls = {};
}

var seenList = Object.keys(seenUrls);

// ── Passer tous les items originaux + item de déduplication ──
var items = $input.all();
items.push({ json: { _seenUrls: seenList } });

return items;
